mapper.select:
select
a.task_id,
a.task_code,
a.task_name,
a.plan_id,
a.area_id,
a.task_type,
a.execute_type,
a.robot_id,
a.date_type,
a.task_source,
a.task_level,
a.start_time,
a.create_time,
a.end_time,
a.create_user_id
from u_patrol_task a
where 1 = 1
 and a.task_id = #{taskId, jdbcType=VARCHAR}
 and a.task_code = #{taskCode, jdbcType=VARCHAR}
 and a.task_name = #{taskName, jdbcType=VARCHAR}
 and a.plan_id = #{planId, jdbcType=BIGINT}
 and a.area_id = #{areaId, jdbcType=VARCHAR}
 and a.task_type = #{taskType, jdbcType=INTEGER}
 and a.execute_type = #{executeType, jdbcType=INTEGER}
 and a.robot_id = #{robotId, jdbcType=BIGINT}
 and a.date_type = #{dateType, jdbcType=VARCHAR}
 and a.task_source = #{taskSource, jdbcType=INTEGER}
